Description: This Terraform configuration creates an AWS SageMaker Image with an associated IAM role that SageMaker can assume. The IAM role includes a trust policy for SageMaker and attaches the AWS-managed `AmazonSageMakerFullAccess` policy so the image can be managed and used by SageMaker services.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the SageMaker Image will be created."
  type        = string
  default     = "us-east-1"
}

variable "sagemaker_image_name" {
  description = "Name of the SageMaker Image."
  type        = string
  default     = "example-sagemaker-image"
}

variable "sagemaker_image_display_name" {
  description = "Display name for the SageMaker Image."
  type        = string
  default     = "Example SageMaker Image"
}

variable "sagemaker_image_description" {
  description = "Description of the SageMaker Image."
  type        = string
  default     = "A custom AWS SageMaker Image created with Terraform."
